var IE = false; //explorer hasznalat
var BROWSERSIZE;
//cookie hasznalat
var COOKIE_USING = true;
var DROUGHT_PARAMS;
var MAP_IS_FORECAST = false;
var NARROW_SCREEN;

/**
 * 
 * @returns {Boolean}iet hasznale  auser
 */
function checkIE() 
{
    var ua = window.navigator.userAgent;
    var msie = ua.indexOf("MSIE ");

    if (msie > 0) // If Internet Explorer, return version number
    {
        IE = true;
        jQuery("body").append('<script src="js/excanvas.min.js"></script>');
    }    
}

//ha betöltött az oldal megnezzuk van-e cookie mert ha van akkor
//egybol kerjuk le az eredmenyt
window.onload = function() 
   {
      BROWSERSIZE = {x:jQuery(window).width(),y:jQuery(window).height()};

      checkIE();

      var cookie = getDroughtCookie();             
      var process=true;            

      if (!document.getElementById("drought_station")) process=false;
      //csak pattern modban fusson automatikusan
      if (document.getElementById("drought_startdate")) process=false;                     

      if (process)
      {
          //saboln esetben csak a valasztott allomast toltjuk be
          //if (type == 'pattern')
          if (cookie)
          {
              if ('patternvoa' in cookie) 
              {
                  jQuery("#drought_station").val(cookie.patternvoa);                            
              }
          } 

          getDroughtPatternData();     
      }
      //sutifigyelmeztetse
      if (!(cookie) || (cookie && !('cookie_using' in cookie)))
      {              
          createDroughtCookieWarningDiv();
          COOKIE_USING = false;
      }  

      //Terkep feliratokhoz
      DROUGHT_PARAMS = {precip : {legendtype:'cont',memo:"("+DROUGHT_TERMS.daily+" "+DROUGHT_TERMS.sum+")",
                                 label:DROUGHT_TERMS.precip,server:"mosaic_pr/ImageServer/",
                                 prefix:'pr024000_', forecast_prefix: 'prx%',unit:'mm'},
                       temp :{legendtype: 'cont',memo:"("+DROUGHT_TERMS.daily+" "+DROUGHT_TERMS.avg+")",
                            label:DROUGHT_TERMS.temperature,server:"mosaic_tm/ImageServer/",
                            prefix:'tm024000_',forecast_prefix: 'tmx%',unit:'°C'},
                       hdis :{legendtype: 'discrete',memo:"",
                            label:DROUGHT_TERMS.HDI0,server:"mosaic_hdis/ImageServer/",
                            prefix:'hdis_', forecast_prefix:'hdisx%'}
          };

      //elég szar csekk arra hogy milyen view van :(
      if (typeof DROUGHT_STAT_MAPPING != 'undefined')
      {         
          //adatok visszakerese
          getDroughtExtremeData(true); 
         // getDroughtMapRecursive('base','20180301',['base']);       
      }      

      NARROW_SCREEN = screen.width < 600 ? true : false;    

      //kkeskeny dvicen a terkep merete a device szelessegehez igazodik
      if (NARROW_SCREEN)
      {
          DROUGHT_MAPSIZE.containersize = screen.width - 110;
          DROUGHT_MAPSIZE.mapsize = screen.width - 110;
      }
      //csak nem keskeny devicen jelenik meg a grafikonon az errtek egermozgasra
      else
      {
         jQuery("<div id='tooltip'></div>").appendTo("body");
      }
      jQuery("<div id='tooltip'></div>").appendTo("body"); 
      //bot trap field elrejtese
      if (document.getElementById("derrick"))
          jQuery("#derrick").hide();                                  
   };

